   158→        { num: 1, nombre: "Introducción a la Mecánica",  href: "modulo_1.html", icono: "🔧" },
   159→        { num: 2, nombre: "Mantenimiento Preventivo",    href: "modulo_2.html", icono: "🛢️" },
   160→        { num: 3, nombre: "Sistemas del Automóvil",      href: "modulo_3.html", icono: "⚙️" },
   161→        { num: 4, nombre: "Diagnóstico Básico",          href: "modulo_4.html", icono: "🔍" }
   162→      ];
   163→
   164→      const FRASES = [
   165→        { min: 0, max: 0, texto: "\"El primer paso es el más importante. Cada gran logro comienza con la decisión de intentarlo. ¡Tú puedes!\"" },
   166→        { min: 1, max: 1, texto: "\"¡Ya diste el primer paso! El camino del aprendizaje se recorre uno a la vez. Sigue adelante.\"" },
   167→        { min: 2, max: 2, texto: "\"¡A mitad del camino! Tu esfuerzo y constancia te han traído hasta aquí. No te detengas.\"" },
   168→        { min: 3, max: 3, texto: "\"¡Casi lo logras! Estás a un paso de completar el curso. Tu dedicación es un ejemplo.\"" },
   169→        { min: 4, max: 4, texto: "\"¡Lo lograste! Completaste todos los módulos. Eres la prueba de que el esfuerzo siempre vale la pena. ¡Felicitaciones!\"" }
   170→      ];
   171→
   172→      function cerrarSesion() {
   173→        localStorage.removeItem("usuario_conecta");
   174→        window.location.href = "inicio.html";
   175→      }
   176→
   177→      async function cargarCuenta() {
   178→        const usuario = JSON.parse(localStorage.getItem("usuario_conecta") || "null");
   179→        if (!usuario) {
   180→          window.location.href = "inicio.html";
   181→          return;
   182→        }
   183→
   184→        // Datos básicos del usuario
   185→        document.getElementById("titulo-bienvenida").textContent = "Hola, " + usuario.nombre + " 👋";
   186→        document.getElementById("user-nombre").textContent = usuario.nombre;
   187→        document.getElementById("dato-nombre").textContent = usuario.nombre;
   188→
   189→        // Cargar datos completos del servidor
   190→        try {
   191→          const resUsuarios = await fetch("/usuarios");
   192→          const todos = await resUsuarios.json();
   193→          const yo = todos.find(u => u.id === usuario.id || u.id === String(usuario.id));
   194→          if (yo) {
   195→            document.getElementById("dato-edad").textContent = yo.edad + " años";
   196→          }
   197→        } catch(e) {}
   198→
   199→        // Cargar progreso
   200→        try {
   201→          const resProgreso = await fetch("/progreso/" + usuario.id);
   202→          const progreso = await resProgreso.json();
   203→
   204→          const completados = progreso.length;
   205→          const porcentaje  = Math.round((completados / 4) * 100);
   206→
   207→          // Frase motivadora
   208→          const fraseDef = FRASES.find(f => completados >= f.min && completados <= f.max);
   209→          if (fraseDef) document.getElementById("frase-motivadora").textContent = fraseDef.texto;
   210→
   211→          // Barra
   212→          document.getElementById("barra-fill").style.width = porcentaje + "%";
   213→          document.getElementById("barra-fill").textContent = porcentaje > 10 ? porcentaje + "%" : "";
   214→          document.getElementById("progreso-texto").textContent =
   215→            completados === 4
   216→              ? "🎉 ¡Completaste todos los módulos!"
   217→              : completados + " de 4 módulos completados";
   218→
   219→          // Chips de módulos
   220→          const grid = document.getElementById("modulos-grid");
   221→          grid.innerHTML = MODULOS_INFO.map(m => {
   222→            const p = progreso.find(pr => pr.modulo === m.num);
   223→            const hecho = !!p;
   224→            return `<div class="modulo-chip ${hecho ? "completado" : "pendiente"}">
   225→              <div class="icono">${m.icono}</div>
   226→              <h4>Módulo ${m.num}</h4>
   227→              <p style="font-size:0.85em; opacity:0.75; margin:0 0 4px;">${m.nombre}</p>
   228→              ${hecho
   229→                ? `<div class="puntaje">Puntaje: <strong>${p.puntaje}%</strong></div>
   230→                   <span class="badge-ok">✓ Completado</span>`
   231→                : `<span class="badge-no">Pendiente</span>`
   232→              }
   233→              <br/><a href="${m.href}" style="font-size:0.8em; margin-top:8px; display:inline-block;">
   234→                ${hecho ? "Repasar →" : "Empezar →"}
   235→              </a>
   236→            </div>`;
   237→          }).join("");
   238→
   239→        } catch(e) {
   240→          document.getElementById("frase-motivadora").textContent =
   241→            "\"Cada día es una nueva oportunidad para aprender y crecer.\"";
   242→        }
   243→      }
   244→
   245→      cargarCuenta();
   246→    </script>
   247→  </body>
   248→</html>
   249→

